import java.util.Scanner;

public class Main {
    static boolean isPrime(int n) {
        if (n < 2) {
            return false;
        }
        for (int d = 2; d * d <= n; d++) {
            if (n % d == 0) {
                return false;
            }
        }
        return true;
    }

    static int nextPrime(int p) {
        int c = p + 1;
        while (!isPrime(c)) {
            c++;
        }
        return c;
    }

    static int previousPrime(int p) {
        int c = p - 1;
        while (!isPrime(c)) {
            c--;
        }
        return c;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.next());
        int lastPrinted = 1;
        for (int i = 1; i <= n; i++) {
            int first = nextPrime(lastPrinted);
            int last = first;
            for (int k = 2; k <= i; k++) {
                last = nextPrime(last);
            }
            if (i % 2 == 1) {
                int p = first;
                for (int k = 1; k <= i; k++) {
                    if (k > 1) {
                        System.out.print(" ");
                    }
                    System.out.print(p);
                    if (k < i) {
                        p = nextPrime(p);
                    }
                }
            } else {
                int p = last;
                for (int k = 1; k <= i; k++) {
                    if (k > 1) {
                        System.out.print(" ");
                    }
                    System.out.print(p);
                    if (k < i) {
                        p = previousPrime(p);
                    }
                }
            }
            System.out.println();
            lastPrinted = last;
        }
    }
}

