public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.next());
        int size = 2 * n - 1;
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                int layer = 1 + Math.min(Math.min(i, j), Math.min(size - 1 - i, size - 1 - j));
                if (j > 0) {
                    System.out.print(" ");
                }
                if (layer % 2 == 1) {
                    System.out.print("*");
                } else {
                    System.out.print("#");
                }
            }
            System.out.println();
        }
    }
}
